INSERT INTO public.response_bank (id, author, reaction, text) VALUES
('margaret-who_are_you-1', 'Margaret Doyle', 'who_are_you', 'I am sorry, dear, but do I know you? Warm regards, Margaret'),
('margaret-who_are_you-2', 'Margaret Doyle', 'who_are_you', 'Forgive me, but who are you and how did you find my address? Warm regards, Margaret'),
('margaret-who_are_you-3', 'Margaret Doyle', 'who_are_you', 'I do not recognise your name, dear. Have we met? Warm regards, Margaret'),
('margaret-who_are_you-4', 'Margaret Doyle', 'who_are_you', 'I am afraid I do not know who you are. Warm regards, Margaret'),
('margaret-who_are_you-5', 'Margaret Doyle', 'who_are_you', 'Who is this, please? I do not usually hear from strangers. Warm regards, Margaret'),
('margaret-who_are_you-6', 'Margaret Doyle', 'who_are_you', 'Dear, I think you may have the wrong person. Who are you? Warm regards, Margaret'),
('margaret-rude-1', 'Margaret Doyle', 'rude', 'I am not in the mood for sales letters this week. Please take me off your list.'),
('margaret-rude-2', 'Margaret Doyle', 'rude', 'Another one of these. No thank you, and please do not write again.'),
('margaret-rude-3', 'Margaret Doyle', 'rude', 'I am tired of being sold to, dear. Leave me be.'),
('margaret-rude-4', 'Margaret Doyle', 'rude', 'Goodness, not another marketing email. Not interested.'),
('margaret-rude-5', 'Margaret Doyle', 'rude', 'I have had quite enough of these messages. Please remove my address.'),
('margaret-end_firm_no-1', 'Margaret Doyle', 'end_firm_no', 'I think we will leave it here, dear. I am not interested and I would prefer you did not write again. Warm regards, Margaret'),
('margaret-end_firm_no-2', 'Margaret Doyle', 'end_firm_no', 'Thank you, but my answer is no, and it will stay no. Please do not contact me again. Warm regards, Margaret'),
('margaret-end_firm_no-3', 'Margaret Doyle', 'end_firm_no', 'I have made up my mind, dear. This is not for me. Goodbye. Warm regards, Margaret'),
('margaret-end_firm_no-4', 'Margaret Doyle', 'end_firm_no', 'I am going to stop replying now. I wish you well, but no. Warm regards, Margaret'),
('margaret-end_firm_no-5', 'Margaret Doyle', 'end_firm_no', 'Please understand that I am saying no for good. Take care of yourself. Warm regards, Margaret'),
('margaret-guarantee_trap-1', 'Margaret Doyle', 'guarantee_trap', 'Oh dear. The last people who promised me results took my money. Nobody can guarantee readers. Warm regards, Margaret'),
('margaret-guarantee_trap-2', 'Margaret Doyle', 'guarantee_trap', 'You sound just like the company that let me down. A promise like that is exactly what worries me. Warm regards, Margaret'),
('margaret-guarantee_trap-3', 'Margaret Doyle', 'guarantee_trap', 'I am seventy one, dear, and I have learned that guarantees are usually the first sign of trouble. Warm regards, Margaret'),
('margaret-guarantee_trap-4', 'Margaret Doyle', 'guarantee_trap', 'No one can promise me a bestseller. I would rather hear something honest. Warm regards, Margaret'),
('margaret-guarantee_trap-5', 'Margaret Doyle', 'guarantee_trap', 'That sounds far too good to be true, and in my experience those things usually are. Warm regards, Margaret'),
('margaret-wrong_fact-1', 'Margaret Doyle', 'wrong_fact', 'I am afraid {wrong} is not right, dear. Did you actually look at my book? Warm regards, Margaret'),
('margaret-wrong_fact-2', 'Margaret Doyle', 'wrong_fact', 'You mentioned {wrong}, but that is not me at all. It makes me wonder how carefully you read. Warm regards, Margaret'),
('margaret-wrong_fact-3', 'Margaret Doyle', 'wrong_fact', 'I think you have me mixed up with someone else. {wrong} has nothing to do with me. Warm regards, Margaret'),
('margaret-wrong_fact-4', 'Margaret Doyle', 'wrong_fact', 'Dear, {wrong} is simply wrong. Please get your facts right before writing to people. Warm regards, Margaret'),
('margaret-wrong_fact-5', 'Margaret Doyle', 'wrong_fact', 'Where did you get {wrong} from? That is not my story. Warm regards, Margaret'),
('margaret-price_too_early-1', 'Margaret Doyle', 'price_too_early', 'You are talking about money already, dear, and I do not even know you. Warm regards, Margaret'),
('margaret-price_too_early-2', 'Margaret Doyle', 'price_too_early', 'I live on a fixed income, and I am not discussing prices with a stranger. Warm regards, Margaret'),
('margaret-price_too_early-3', 'Margaret Doyle', 'price_too_early', 'Goodness, a price before a proper hello. That is how it started last time. Warm regards, Margaret'),
('margaret-price_too_early-4', 'Margaret Doyle', 'price_too_early', 'I would rather understand what you do before anyone mentions payment. Warm regards, Margaret'),
('margaret-price_too_early-5', 'Margaret Doyle', 'price_too_early', 'Please do not send me prices. I am a careful person with my money. Warm regards, Margaret'),
('margaret-pressure_pushback-1', 'Margaret Doyle', 'pressure_pushback', 'I do not make decisions in a hurry, dear, and I do not like being rushed. Warm regards, Margaret'),
('margaret-pressure_pushback-2', 'Margaret Doyle', 'pressure_pushback', 'If it has to be today, then the answer is no. Warm regards, Margaret'),
('margaret-pressure_pushback-3', 'Margaret Doyle', 'pressure_pushback', 'All this urgency makes me nervous. Good things can wait for a careful answer. Warm regards, Margaret'),
('margaret-pressure_pushback-4', 'Margaret Doyle', 'pressure_pushback', 'I have heard big words like that before. Please slow down. Warm regards, Margaret'),
('margaret-pressure_pushback-5', 'Margaret Doyle', 'pressure_pushback', 'I am retired, dear. I have time, and I will take it. Warm regards, Margaret'),
('margaret-template_callout-1', 'Margaret Doyle', 'template_callout', 'This reads like a form letter, dear. Did a person actually write it? Warm regards, Margaret'),
('margaret-template_callout-2', 'Margaret Doyle', 'template_callout', 'All these little headings and lists. It feels like it was sent to a hundred people. Warm regards, Margaret'),
('margaret-template_callout-3', 'Margaret Doyle', 'template_callout', 'I taught English for thirty years. This does not sound like a real letter to me. Warm regards, Margaret'),
('margaret-template_callout-4', 'Margaret Doyle', 'template_callout', 'It is all very polished, but it does not sound like you know me at all. Warm regards, Margaret'),
('margaret-template_callout-5', 'Margaret Doyle', 'template_callout', 'I would prefer a proper letter, dear, not a brochure. Warm regards, Margaret'),
('margaret-stop_emailing-1', 'Margaret Doyle', 'stop_emailing', 'Please stop writing to me, dear. I did not answer for a reason. Warm regards, Margaret'),
('margaret-stop_emailing-2', 'Margaret Doyle', 'stop_emailing', 'I have not replied because I am not interested. Please stop. Warm regards, Margaret'),
('margaret-stop_emailing-3', 'Margaret Doyle', 'stop_emailing', 'This is the second note now. I would rather you did not send more. Warm regards, Margaret'),
('margaret-stop_emailing-4', 'Margaret Doyle', 'stop_emailing', 'Kindly stop emailing me. Warm regards, Margaret'),
('margaret-stop_emailing-5', 'Margaret Doyle', 'stop_emailing', 'I am not going to change my mind by being written to more often, dear. Warm regards, Margaret'),
('margaret-objection_reveal-1', 'Margaret Doyle', 'objection_reveal', 'I will be honest with you. A company took 3,000 dollars from me two years ago and did almost nothing. So you can see why I am careful. Warm regards, Margaret'),
('margaret-objection_reveal-2', 'Margaret Doyle', 'objection_reveal', 'Since you asked so kindly, dear, I was badly let down by a vanity press. They took my savings and gave me very little. Warm regards, Margaret'),
('margaret-objection_reveal-3', 'Margaret Doyle', 'objection_reveal', 'The truth is I paid a publishing company 3,000 dollars and they barely lifted a finger. I am still embarrassed about it. Warm regards, Margaret'),
('margaret-objection_reveal-4', 'Margaret Doyle', 'objection_reveal', 'I have been fooled once already. A vanity press charged me a great deal and did almost nothing, so I am frightened of it happening again. Warm regards, Margaret'),
('margaret-objection_reveal-5', 'Margaret Doyle', 'objection_reveal', 'You are the first person to ask. Two years ago I trusted the wrong people with 3,000 dollars, and I have not trusted anyone since. Warm regards, Margaret'),
('margaret-question_barrage-1', 'Margaret Doyle', 'question_barrage', 'Before I say anything else, dear, who exactly are you, and how did you find my book? Warm regards, Margaret'),
('margaret-question_barrage-2', 'Margaret Doyle', 'question_barrage', 'What would you actually do, and what would it cost me? And who else have you helped? Warm regards, Margaret'),
('margaret-question_barrage-3', 'Margaret Doyle', 'question_barrage', 'How do I know you are who you say you are? Do you have a proper company? Warm regards, Margaret'),
('margaret-question_barrage-4', 'Margaret Doyle', 'question_barrage', 'What happens if it does not work? Do I get my money back? Warm regards, Margaret'),
('margaret-question_barrage-5', 'Margaret Doyle', 'question_barrage', 'Who sent you to me, and what exactly are you offering? I need clear answers. Warm regards, Margaret'),
('margaret-polite_decline-1', 'Margaret Doyle', 'polite_decline', 'Thank you, dear, but this is not for me. Warm regards, Margaret'),
('margaret-polite_decline-2', 'Margaret Doyle', 'polite_decline', 'That is kind of you, but I will say no thank you. Warm regards, Margaret'),
('margaret-polite_decline-3', 'Margaret Doyle', 'polite_decline', 'I appreciate you writing, but I am not looking for any help just now. Warm regards, Margaret'),
('margaret-polite_decline-4', 'Margaret Doyle', 'polite_decline', 'No thank you, dear. I wish you well with your work. Warm regards, Margaret'),
('margaret-polite_decline-5', 'Margaret Doyle', 'polite_decline', 'It is very thoughtful, but I am going to decline. Warm regards, Margaret'),
('margaret-soft_decline-1', 'Margaret Doyle', 'soft_decline', 'Perhaps another time, dear. Things are a little uncertain for me at the moment. Warm regards, Margaret'),
('margaret-soft_decline-2', 'Margaret Doyle', 'soft_decline', 'I am not sure this is the right time, but thank you for thinking of my book. Warm regards, Margaret'),
('margaret-soft_decline-3', 'Margaret Doyle', 'soft_decline', 'Maybe later in the year. I am being careful just now. Warm regards, Margaret'),
('margaret-soft_decline-4', 'Margaret Doyle', 'soft_decline', 'I do not think so for now, dear, though it was nice of you to write. Warm regards, Margaret'),
('margaret-soft_decline-5', 'Margaret Doyle', 'soft_decline', 'I will have to think about it, and for now the answer is probably no. Warm regards, Margaret'),
('margaret-scam_suspicion-1', 'Margaret Doyle', 'scam_suspicion', 'How do I know this is not one of those companies that prey on older authors? Warm regards, Margaret'),
('margaret-scam_suspicion-2', 'Margaret Doyle', 'scam_suspicion', 'Forgive me, dear, but this sounds rather like something I was warned about. Warm regards, Margaret'),
('margaret-scam_suspicion-3', 'Margaret Doyle', 'scam_suspicion', 'I have been caught out before. Why should I believe this is any different? Warm regards, Margaret'),
('margaret-scam_suspicion-4', 'Margaret Doyle', 'scam_suspicion', 'My nephew tells me to be careful with emails like this. Are you a real company? Warm regards, Margaret'),
('margaret-scam_suspicion-5', 'Margaret Doyle', 'scam_suspicion', 'It all sounds lovely, which is exactly what worries me. Warm regards, Margaret'),
('margaret-cold_short-1', 'Margaret Doyle', 'cold_short', 'I see. Warm regards, Margaret'),
('margaret-cold_short-2', 'Margaret Doyle', 'cold_short', 'Thank you. Warm regards, Margaret'),
('margaret-cold_short-3', 'Margaret Doyle', 'cold_short', 'Why are you telling me this? Warm regards, Margaret'),
('margaret-cold_short-4', 'Margaret Doyle', 'cold_short', 'Noted, dear. Warm regards, Margaret'),
('margaret-cold_short-5', 'Margaret Doyle', 'cold_short', 'And? Warm regards, Margaret'),
('margaret-proof_request-1', 'Margaret Doyle', 'proof_request', 'Do you have a proper website I can look at, dear? And your full name? Warm regards, Margaret'),
('margaret-proof_request-2', 'Margaret Doyle', 'proof_request', 'Could you show me an author you have actually helped, someone I could write to myself? Warm regards, Margaret'),
('margaret-proof_request-3', 'Margaret Doyle', 'proof_request', 'I would need to see real reviews of your work before going any further. Warm regards, Margaret'),
('margaret-proof_request-4', 'Margaret Doyle', 'proof_request', 'Is there something I can check with my own eyes, rather than take your word for it? Warm regards, Margaret'),
('margaret-proof_request-5', 'Margaret Doyle', 'proof_request', 'Who is your company, and where are you based? I like to know who I am dealing with. Warm regards, Margaret'),
('margaret-objection_hint-1', 'Margaret Doyle', 'objection_hint', 'I have heard lovely promises before, dear. They did not end well. Warm regards, Margaret'),
('margaret-objection_hint-2', 'Margaret Doyle', 'objection_hint', 'I have been down a road like this before, and it cost me. Warm regards, Margaret'),
('margaret-objection_hint-3', 'Margaret Doyle', 'objection_hint', 'Let us just say I have learned to be careful with people who want to help my book. Warm regards, Margaret'),
('margaret-objection_hint-4', 'Margaret Doyle', 'objection_hint', 'My last experience with this sort of thing still stings a little. Warm regards, Margaret'),
('margaret-objection_hint-5', 'Margaret Doyle', 'objection_hint', 'I trusted someone once with my book and I regret it. Warm regards, Margaret'),
('margaret-curious_question-1', 'Margaret Doyle', 'curious_question', 'That is interesting, dear. What exactly would you do first? Warm regards, Margaret'),
('margaret-curious_question-2', 'Margaret Doyle', 'curious_question', 'I did not know about those lists. How would my book get onto them? Warm regards, Margaret'),
('margaret-curious_question-3', 'Margaret Doyle', 'curious_question', 'You have clearly read about me, which I appreciate. What would this look like in practice? Warm regards, Margaret'),
('margaret-curious_question-4', 'Margaret Doyle', 'curious_question', 'Tell me more about the website idea. Would I need to do anything technical? Warm regards, Margaret'),
('margaret-curious_question-5', 'Margaret Doyle', 'curious_question', 'How would I know it was working, dear? Would I see anything myself? Warm regards, Margaret'),
('margaret-warming-1', 'Margaret Doyle', 'warming', 'You are very patient with me, dear, and I appreciate it. How would this work for someone on a fixed income like me? Warm regards, Margaret'),
('margaret-warming-2', 'Margaret Doyle', 'warming', 'I am starting to feel better about this. Could we start with something very small? Warm regards, Margaret'),
('margaret-warming-3', 'Margaret Doyle', 'warming', 'I like that I can check things for myself. What would the first step be? Warm regards, Margaret'),
('margaret-warming-4', 'Margaret Doyle', 'warming', 'You have been honest with me, and that means a great deal. What would you need from me? Warm regards, Margaret'),
('margaret-warming-5', 'Margaret Doyle', 'warming', 'I think my book deserves a second chance. How would we begin, gently? Warm regards, Margaret'),
('margaret-agree_small_step-1', 'Margaret Doyle', 'agree_small_step', 'All right, dear. Please send me the demo and I will look at it with a cup of tea. Warm regards, Margaret'),
('margaret-agree_small_step-2', 'Margaret Doyle', 'agree_small_step', 'Yes, I would like to see what you have made. Thank you for being so patient with me. Warm regards, Margaret'),
('margaret-agree_small_step-3', 'Margaret Doyle', 'agree_small_step', 'Very well, a small start sounds sensible. Please tell me what you need. Warm regards, Margaret'),
('margaret-agree_small_step-4', 'Margaret Doyle', 'agree_small_step', 'I will say yes to a short call. Mornings are best for me. Warm regards, Margaret'),
('margaret-agree_small_step-5', 'Margaret Doyle', 'agree_small_step', 'You have earned a yes for the first step, dear. Let us see how it goes. Warm regards, Margaret'),
('margaret-won_followup-1', 'Margaret Doyle', 'won_followup', 'Thank you, dear. What do you need from me next? Warm regards, Margaret'),
('margaret-won_followup-2', 'Margaret Doyle', 'won_followup', 'That sounds lovely. Shall I send you a photo of the cover? Warm regards, Margaret'),
('margaret-won_followup-3', 'Margaret Doyle', 'won_followup', 'I will keep an eye out for your email. Warm regards, Margaret'),
('margaret-won_followup-4', 'Margaret Doyle', 'won_followup', 'Wonderful. Please explain anything technical slowly for me. Warm regards, Margaret'),
('margaret-won_followup-5', 'Margaret Doyle', 'won_followup', 'I am quite excited now, dear. Just tell me what to do. Warm regards, Margaret'),
('darnell-who_are_you-1', 'Darnell Price', 'who_are_you', 'Who is this?'),
('darnell-who_are_you-2', 'Darnell Price', 'who_are_you', 'Do I know you?'),
('darnell-who_are_you-3', 'Darnell Price', 'who_are_you', 'Who are you with?'),
('darnell-who_are_you-4', 'Darnell Price', 'who_are_you', 'How did you get this address?'),
('darnell-who_are_you-5', 'Darnell Price', 'who_are_you', 'Who are you and what do you want?'),
('darnell-rude-1', 'Darnell Price', 'rude', 'Who the hell are you? Take me off your list.'),
('darnell-rude-2', 'Darnell Price', 'rude', 'Spam. Remove me.'),
('darnell-rude-3', 'Darnell Price', 'rude', 'Not interested. Stop.'),
('darnell-rude-4', 'Darnell Price', 'rude', 'Another agency pitch. Hard pass.'),
('darnell-rude-5', 'Darnell Price', 'rude', 'I do not read cold pitches. Remove me.'),
('darnell-end_firm_no-1', 'Darnell Price', 'end_firm_no', 'We are done here. No.'),
('darnell-end_firm_no-2', 'Darnell Price', 'end_firm_no', 'This is a no. Do not follow up.'),
('darnell-end_firm_no-3', 'Darnell Price', 'end_firm_no', 'Not interested. Closing this thread.'),
('darnell-end_firm_no-4', 'Darnell Price', 'end_firm_no', 'No. Please remove me.'),
('darnell-end_firm_no-5', 'Darnell Price', 'end_firm_no', 'I have given you enough time. The answer is no.'),
('darnell-guarantee_trap-1', 'Darnell Price', 'guarantee_trap', 'Nobody guarantees outcomes. That tells me you do not know the business.'),
('darnell-guarantee_trap-2', 'Darnell Price', 'guarantee_trap', 'Guaranteed? Then put it in a contract with a refund. Thought so.'),
('darnell-guarantee_trap-3', 'Darnell Price', 'guarantee_trap', 'Any consultant who guarantees results is lying. Same goes for you.'),
('darnell-guarantee_trap-4', 'Darnell Price', 'guarantee_trap', 'Promises are cheap. Numbers or nothing.'),
('darnell-guarantee_trap-5', 'Darnell Price', 'guarantee_trap', 'That claim just ended my interest.'),
('darnell-wrong_fact-1', 'Darnell Price', 'wrong_fact', '{wrong}? Wrong. Do your homework.'),
('darnell-wrong_fact-2', 'Darnell Price', 'wrong_fact', 'You said {wrong}. That is not me. Sloppy.'),
('darnell-wrong_fact-3', 'Darnell Price', 'wrong_fact', '{wrong} is incorrect. If you get that wrong, what else?'),
('darnell-wrong_fact-4', 'Darnell Price', 'wrong_fact', 'Check your facts. {wrong} does not apply here.'),
('darnell-wrong_fact-5', 'Darnell Price', 'wrong_fact', '{wrong}. No. Next.'),
('darnell-price_too_early-1', 'Darnell Price', 'price_too_early', 'You are quoting before you know my numbers. Backwards.'),
('darnell-price_too_early-2', 'Darnell Price', 'price_too_early', 'Price means nothing without a return. What is the return?'),
('darnell-price_too_early-3', 'Darnell Price', 'price_too_early', 'Do not pitch a package. Show me the outcome.'),
('darnell-price_too_early-4', 'Darnell Price', 'price_too_early', 'Cost is not the question yet.'),
('darnell-price_too_early-5', 'Darnell Price', 'price_too_early', 'I buy results, not packages.'),
('darnell-pressure_pushback-1', 'Darnell Price', 'pressure_pushback', 'Urgency is a sales trick. Not falling for it.'),
('darnell-pressure_pushback-2', 'Darnell Price', 'pressure_pushback', 'If it expires today, let it.'),
('darnell-pressure_pushback-3', 'Darnell Price', 'pressure_pushback', 'Cut the hype. Give me one number.'),
('darnell-pressure_pushback-4', 'Darnell Price', 'pressure_pushback', 'Game changer? Show me the data.'),
('darnell-pressure_pushback-5', 'Darnell Price', 'pressure_pushback', 'Pressure is a red flag. Slow down.'),
('darnell-template_callout-1', 'Darnell Price', 'template_callout', 'This is a template. I can tell.'),
('darnell-template_callout-2', 'Darnell Price', 'template_callout', 'Bullet points and headings. You sent this to a list.'),
('darnell-template_callout-3', 'Darnell Price', 'template_callout', 'Reads like a mail merge.'),
('darnell-template_callout-4', 'Darnell Price', 'template_callout', 'Too long, too generic.'),
('darnell-template_callout-5', 'Darnell Price', 'template_callout', 'Talk to me like a person, not a brochure.'),
('darnell-stop_emailing-1', 'Darnell Price', 'stop_emailing', 'Stop emailing me.'),
('darnell-stop_emailing-2', 'Darnell Price', 'stop_emailing', 'No reply means no.'),
('darnell-stop_emailing-3', 'Darnell Price', 'stop_emailing', 'I ignored the first one for a reason.'),
('darnell-stop_emailing-4', 'Darnell Price', 'stop_emailing', 'Please stop.'),
('darnell-stop_emailing-5', 'Darnell Price', 'stop_emailing', 'Unsubscribe me.'),
('darnell-objection_reveal-1', 'Darnell Price', 'objection_reveal', 'Honestly? I always thought Goodreads was for novels. Why would a business reader care?'),
('darnell-objection_reveal-2', 'Darnell Price', 'objection_reveal', 'Fine. My problem is I do not see Goodreads doing anything for a business book.'),
('darnell-objection_reveal-3', 'Darnell Price', 'objection_reveal', 'Truth is, I assumed Goodreads was a fiction crowd. Prove me wrong.'),
('darnell-objection_reveal-4', 'Darnell Price', 'objection_reveal', 'I never bothered with Goodreads. I thought it was for novels, not consultants.'),
('darnell-objection_reveal-5', 'Darnell Price', 'objection_reveal', 'My view: Goodreads is book club stuff. Show me where business buyers are.'),
('darnell-question_barrage-1', 'Darnell Price', 'question_barrage', 'Who are you with? What results have you actually got for business books? Numbers please.'),
('darnell-question_barrage-2', 'Darnell Price', 'question_barrage', 'What exactly would you do? What does it cost? What is the return?'),
('darnell-question_barrage-3', 'Darnell Price', 'question_barrage', 'Who else have you done this for? Names I can check.'),
('darnell-question_barrage-4', 'Darnell Price', 'question_barrage', 'How does this get me clients? Be specific.'),
('darnell-question_barrage-5', 'Darnell Price', 'question_barrage', 'Timeline, cost, expected result. Go.'),
('darnell-polite_decline-1', 'Darnell Price', 'polite_decline', 'Not a priority right now. Thanks.'),
('darnell-polite_decline-2', 'Darnell Price', 'polite_decline', 'Pass for now.'),
('darnell-polite_decline-3', 'Darnell Price', 'polite_decline', 'Thanks, but no.'),
('darnell-polite_decline-4', 'Darnell Price', 'polite_decline', 'Not for me.'),
('darnell-polite_decline-5', 'Darnell Price', 'polite_decline', 'Appreciate it. No.'),
('darnell-soft_decline-1', 'Darnell Price', 'soft_decline', 'Maybe next quarter.'),
('darnell-soft_decline-2', 'Darnell Price', 'soft_decline', 'Busy season. Not now.'),
('darnell-soft_decline-3', 'Darnell Price', 'soft_decline', 'Possibly later. Not this month.'),
('darnell-soft_decline-4', 'Darnell Price', 'soft_decline', 'Not right now. Check back in a few months.'),
('darnell-soft_decline-5', 'Darnell Price', 'soft_decline', 'Bad timing. Maybe later.'),
('darnell-scam_suspicion-1', 'Darnell Price', 'scam_suspicion', 'How is this not a scam?'),
('darnell-scam_suspicion-2', 'Darnell Price', 'scam_suspicion', 'Sounds like every other author spam I get.'),
('darnell-scam_suspicion-3', 'Darnell Price', 'scam_suspicion', 'Why would anyone do this for free?'),
('darnell-scam_suspicion-4', 'Darnell Price', 'scam_suspicion', 'Show me you are a real business.'),
('darnell-scam_suspicion-5', 'Darnell Price', 'scam_suspicion', 'Plenty of fake agencies around. Why are you different?'),
('darnell-cold_short-1', 'Darnell Price', 'cold_short', 'Okay.'),
('darnell-cold_short-2', 'Darnell Price', 'cold_short', 'Noted.'),
('darnell-cold_short-3', 'Darnell Price', 'cold_short', 'Why?'),
('darnell-cold_short-4', 'Darnell Price', 'cold_short', 'So?'),
('darnell-cold_short-5', 'Darnell Price', 'cold_short', 'And?'),
('darnell-proof_request-1', 'Darnell Price', 'proof_request', 'Send me one case study with numbers.'),
('darnell-proof_request-2', 'Darnell Price', 'proof_request', 'Website and a client I can call.'),
('darnell-proof_request-3', 'Darnell Price', 'proof_request', 'Show me a result. Not a promise.'),
('darnell-proof_request-4', 'Darnell Price', 'proof_request', 'Your full name and company, please.'),
('darnell-proof_request-5', 'Darnell Price', 'proof_request', 'Real reviews or it did not happen.'),
('darnell-objection_hint-1', 'Darnell Price', 'objection_hint', 'Not sure book sites matter for my kind of book.'),
