INSERT INTO public.model_lines (id, author, reaction, text) VALUES
('margaret-no_reply', 'Margaret Doyle', 'no_reply', 'Hi Margaret, Your years teaching and a lighthouse keeper''s daughter as a heroine is a lovely pairing. Twelve readers have rated The Lighthouse Keeper''s Daughter and the average is 4.6, yet I could not find a website for you. Would you like me to send you the small demo website I built, which costs you nothing?'),
('margaret-who_are_you', 'Margaret Doyle', 'who_are_you', 'Hi Margaret, my name is Emmanuel Sunday and I run HQ360 at hq360.space. I wrote because twelve readers have rated The Lighthouse Keeper''s Daughter and the average is 4.6, yet I could not find a website for you. Would it help if I sent you the small demo website I built, which costs you nothing?'),
('margaret-rude', 'Margaret Doyle', 'rude', 'Hi Margaret, you are right that you did not ask for this, and I am sorry for the intrusion. Twelve readers have rated The Lighthouse Keeper''s Daughter and the average is 4.6, yet I could not find a website for you. If that is ever useful, would you like me to send it?'),
('margaret-end_firm_no', 'Margaret Doyle', 'end_firm_no', 'Thank you for the honest answer, Margaret. I will not write again, and I wish the book every success.'),
('margaret-guarantee_trap', 'Margaret Doyle', 'guarantee_trap', 'You are right, Margaret, nobody can guarantee results, and I should not have said it. What I can do is send you the small demo website I built, which costs you nothing so you can judge for yourself.'),
('margaret-wrong_fact', 'Margaret Doyle', 'wrong_fact', 'You are right, Margaret, that was my mistake and I am sorry. Twelve readers have rated The Lighthouse Keeper''s Daughter and the average is 4.6, yet I could not find a website for you.'),
('margaret-price_too_early', 'Margaret Doyle', 'price_too_early', 'Fair point, Margaret, let us leave money aside. Has anyone tried to help with the book before, and how did that go for you?'),
('margaret-pressure_pushback', 'Margaret Doyle', 'pressure_pushback', 'There is no deadline at all, Margaret. Take whatever time you need. Twelve readers have rated The Lighthouse Keeper''s Daughter and the average is 4.6, yet I could not find a website for you.'),
('margaret-template_callout', 'Margaret Doyle', 'template_callout', 'Fair, Margaret, that read like a template. Plainly: twelve readers have rated The Lighthouse Keeper''s Daughter and the average is 4.6, yet I could not find a website for you. Would you like to see it?'),
('margaret-stop_emailing', 'Margaret Doyle', 'stop_emailing', 'Understood, Margaret. This is my last note. If you ever want the small demo website I built, which costs you nothing, just reply and it is yours.'),
('margaret-objection_reveal', 'Margaret Doyle', 'objection_reveal', 'Thank you for telling me that, Margaret. I understand why you are careful, and you should be. Nothing is paid until you have seen the work and checked it yourself. Would a small first step you can check yourself feel comfortable?'),
('margaret-question_barrage', 'Margaret Doyle', 'question_barrage', 'Good questions, Margaret. I am Emmanuel Sunday from HQ360, you can see our work at hq360.space. Twelve readers have rated The Lighthouse Keeper''s Daughter and the average is 4.6, yet I could not find a website for you. Would you like me to send the small demo website I built, which costs you nothing?'),
('margaret-polite_decline', 'Margaret Doyle', 'polite_decline', 'Totally fair, Margaret. Before I close your file, has anyone tried to help with the book before, and how did that go for you?'),
('margaret-soft_decline', 'Margaret Doyle', 'soft_decline', 'That makes sense, Margaret. Could I send you the small demo website I built, which costs you nothing so it is there whenever the timing is right?'),
('margaret-scam_suspicion', 'Margaret Doyle', 'scam_suspicion', 'You are right to ask, Margaret. I understand why you are careful, and you should be. Nothing is paid until you have seen the work and checked it yourself.'),
('margaret-cold_short', 'Margaret Doyle', 'cold_short', 'Because twelve readers have rated The Lighthouse Keeper''s Daughter and the average is 4.6, yet I could not find a website for you. Would you like me to show you?'),
('margaret-proof_request', 'Margaret Doyle', 'proof_request', 'Of course, Margaret. I am Emmanuel Sunday, HQ360, hq360.space, and I can put you in touch with an author we helped. Twelve readers have rated The Lighthouse Keeper''s Daughter and the average is 4.6, yet I could not find a website for you.'),
('margaret-objection_hint', 'Margaret Doyle', 'objection_hint', 'That sounds like it has been on your mind, Margaret. Has anyone tried to help with the book before, and how did that go for you?'),
('margaret-curious_question', 'Margaret Doyle', 'curious_question', 'Great question, Margaret. First I would send you the small demo website I built, which costs you nothing, then you decide if it is worth going further. Would that work?'),
('margaret-warming', 'Margaret Doyle', 'warming', 'I am glad, Margaret. The first step is the small demo website I built, which costs you nothing. Are you happy for me to send it today?'),
('margaret-agree_small_step', 'Margaret Doyle', 'agree_small_step', 'Thank you, Margaret. I will send it today, and once you have seen it we can agree the scope, timeline and terms in writing.'),
('margaret-won_followup', 'Margaret Doyle', 'won_followup', 'Wonderful, Margaret. I will send everything in writing first, so you know exactly what happens and when.'),
('darnell-no_reply', 'Darnell Price', 'no_reply', 'Hi Darnell, Run the Numbers is clearly working as a door opener for your consulting. Your book page still shows the old edition, so a speaker planner who clicks through sees an outdated pitch. Would you like me to send you a one page plan showing how the book page could bring in speaking enquiries?'),
('darnell-who_are_you', 'Darnell Price', 'who_are_you', 'Hi Darnell, my name is Emmanuel Sunday and I run HQ360 at hq360.space. I wrote because your book page still shows the old edition, so a speaker planner who clicks through sees an outdated pitch. Would it help if I sent you a one page plan showing how the book page could bring in speaking enquiries?'),
