('harold-cold_short', 'Harold Jensen', 'cold_short', 'Because thirty one readers have rated it at 4.7, which is a remarkable welcome for a history book. Would you like me to show you?'),
('harold-proof_request', 'Harold Jensen', 'proof_request', 'Of course, Harold. I am Emmanuel Sunday, HQ360, hq360.space, and I can put you in touch with an author we helped. Thirty one readers have rated it at 4.7, which is a remarkable welcome for a history book.'),
('harold-objection_hint', 'Harold Jensen', 'objection_hint', 'That sounds like it has been on your mind, Harold. Would it help if I explained, step by step, how readers find history books online?'),
('harold-curious_question', 'Harold Jensen', 'curious_question', 'Great question, Harold. First I would send you a plain explanation, in one page, of where readers find books like yours, then you decide if it is worth going further. Would that work?'),
('harold-warming', 'Harold Jensen', 'warming', 'I am glad, Harold. The first step is a plain explanation, in one page, of where readers find books like yours. Are you happy for me to send it today?'),
('harold-agree_small_step', 'Harold Jensen', 'agree_small_step', 'Thank you, Harold. I will send it today, and once you have seen it we can agree the scope, timeline and terms in writing.'),
('harold-won_followup', 'Harold Jensen', 'won_followup', 'Wonderful, Harold. I will send everything in writing first, so you know exactly what happens and when.')
INSERT INTO public.hints (id, rule, text) VALUES
('no_message', 'no_message', 'Open with something only this author would recognise: their name, their book and one real fact from your research.'),
('after_no_reply', 'after_no_reply', 'Your message was easy to ignore. Add one specific, useful thing you found about the book.'),
('after_wrong_fact', 'after_wrong_fact', 'Correct the mistake honestly, then stick only to facts on the research card.'),
('after_price_too_early', 'after_price_too_early', 'Park the price. Show value first and ask what matters to them.'),
('after_guarantee_trap', 'after_guarantee_trap', 'Never promise results. Say what you will actually do and how they can check it.'),
('after_pressure_pushback', 'after_pressure_pushback', 'Drop the urgency. Give them room and one honest reason to keep talking.'),
('after_template_callout', 'after_template_callout', 'Write like a person, not a brochure. No lists, no labels, no long dashes.'),
('after_questions', 'after_questions', 'Answer every question they asked, clearly and honestly, before you add anything new.'),
('cold_unrevealed', 'cold_unrevealed', 'Ask a caring question about their experience so far. Their real worry is hiding behind the no.'),
('revealed_not_warm', 'revealed_not_warm', 'Answer their real worry directly, then offer one small, low risk next step.'),
('warm', 'warm', 'Ask for a small yes with one clear, easy question.'),
('weak_personal', 'weak_personal', 'Use their name and their book, and add one real fact from the research card.'),
('weak_value', 'weak_value', 'Give something before you ask: a list position, a screenshot or the demo you built.'),
('weak_question', 'weak_question', 'End with one clear, easy question so they know how to reply.'),
('weak_length', 'weak_length', 'Shorter is stronger. Five to eight plain sentences is plenty.'),
('default', 'default', 'Keep it personal, give one useful thing, and end with one easy question.')
INSERT INTO public.feedback (id, signal, kind, text) VALUES
('usesFacts-worked', 'usesFacts', 'worked', 'You used real details from your research, which earns trust fast.'),
('empathy-worked', 'empathy', 'worked', 'You acknowledged their feelings instead of arguing.'),
('proof-worked', 'proof', 'worked', 'You offered something they could check for themselves.'),
('objectionKey-worked', 'objectionKey', 'worked', 'You asked the right question and uncovered their real worry.'),
('value-worked', 'value', 'worked', 'You gave something useful before asking for anything.'),
('personal-worked', 'personal', 'worked', 'You used their name and their book, so it felt written for them.'),
('asksAboutThem-worked', 'asksAboutThem', 'worked', 'You asked about them, not just about your offer.'),
('oneQuestion-worked', 'oneQuestion', 'worked', 'You ended with one clear question that was easy to answer.'),
('default-worked', 'default', 'worked', 'You kept the conversation going and stayed polite.'),
('lowEffort-change', 'lowEffort', 'change', 'Your opening could have been sent to anyone, so it was ignored.'),
('wrongFact-change', 'wrongFact', 'change', 'You stated a detail that was not in your research. Error Hunters end conversations over that.'),
('priceTalk-change', 'priceTalk', 'change', 'You raised money before they saw any value.'),
('guarantee-change', 'guarantee', 'change', 'You promised results. That is the fastest way to sound like a scam.'),
('template-change', 'template', 'change', 'Your message looked like a template. Write like a person.'),
('contractions-change', 'contractions', 'change', 'House style: write I would, do not, it is, without contractions.'),
('aiTells-change', 'aiTells', 'change', 'Long dashes and words like leverage or elevate sound machine written. Use plain words.'),
('pressure-change', 'pressure', 'change', 'Urgency and pressure made them back away. Give them room.'),
('hype-change', 'hype', 'change', 'Hype words made it sound like an advert. Say plainly what you would do.'),
('repeatPitch-change', 'repeatPitch', 'change', 'You repeated your pitch instead of adding something new.'),
('tooManyQuestions-change', 'tooManyQuestions', 'change', 'Too many questions at once. Ask one.'),
('tooLong-change', 'tooLong', 'change', 'Your message was too long. Keep it to five to eight sentences.'),
('noValue-change', 'noValue', 'change', 'You never gave them anything useful. Lead with a fact, a screenshot or a demo.'),
('noQuestion-change', 'noQuestion', 'change', 'End each message with one easy question.'),
('missedObjection-change', 'missedObjection', 'change', 'You never uncovered their real worry. Ask a caring question about their experience.'),
('default-change', 'default', 'change', 'Make every message more specific to this author and this book.'),
('summary_won-summary', 'summary_won', 'summary', 'You earned their trust step by step and won a real next step.'),
('summary_warming-summary', 'summary_warming', 'summary', 'You built real trust. One clear, low risk ask would have closed it.'),
('summary_neutral-summary', 'summary_neutral', 'summary', 'They were listening, but you had not yet given them a strong reason to say yes.'),
('summary_cooling-summary', 'summary_cooling', 'summary', 'They stayed wary. More proof and a caring question would have opened them up.'),
('summary_lost-summary', 'summary_lost', 'summary', 'The author never trusted you enough to keep talking.')
